const all = $input.all();
const rows = all.flatMap(item => {
  const d = item.json;
  return Array.isArray(d) ? d : [d];
});
if (rows.length === 0) {
  // Nenhum post sem capa — execução termina aqui
  return [];
}
return rows.map(row => ({ json: row }));

const meta   = $input.item.json;
const dbRow  = $('IF Conta').item.json;
if (meta.error) throw new Error('Meta API error post_id=' + dbRow.post_id + ': ' + JSON.stringify(meta.error));
const post_id   = String(dbRow.post_id);
const username  = dbRow.username;
const mediaType = meta.media_type || dbRow.media_type;
let coverSourceUrl, coverStrategy;
if (mediaType === 'IMAGE') {
  coverSourceUrl = meta.media_url || null;
  if (!coverSourceUrl) throw new Error('IMAGE sem media_url: ' + post_id);
  coverStrategy = 'IMAGE → media_url';
} else if (mediaType === 'VIDEO') {
  coverSourceUrl = meta.thumbnail_url || null;
  if (!coverSourceUrl) throw new Error('VIDEO sem thumbnail_url: ' + post_id);
  coverStrategy = 'VIDEO → thumbnail_url';
} else if (mediaType === 'CAROUSEL_ALBUM') {
  const child = (meta.children?.data || [])[0] || null;
  if (!child) throw new Error('CAROUSEL sem filhos: ' + post_id);
  if (child.media_type === 'VIDEO') {
    coverSourceUrl = child.thumbnail_url || null;
    if (!coverSourceUrl) throw new Error('CAROUSEL filho VIDEO sem thumbnail_url: ' + post_id);
    coverStrategy = 'CAROUSEL → filho[0] VIDEO → thumbnail_url';
  } else {
    coverSourceUrl = child.media_url || null;
    if (!coverSourceUrl) throw new Error('CAROUSEL filho IMAGE sem media_url: ' + post_id);
    coverStrategy = 'CAROUSEL → filho[0] IMAGE → media_url';
  }
} else {
  throw new Error('media_type desconhecido: ' + mediaType + ' post_id=' + post_id);
}
return { json: { post_id, username, media_type: mediaType, cover_source_url: coverSourceUrl, cover_strategy: coverStrategy }};

const cover  = $('Extrair Cover URL').item.json;
const item   = $input.item;
if (item.json?.error) throw new Error('Download falhou post_id=' + cover.post_id + ': ' + JSON.stringify(item.json.error));
const binary = item.binary?.data;
if (!binary) throw new Error('Sem binário post_id=' + cover.post_id);
const mime = (binary.mimeType || '').toLowerCase();
const MIMES = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif' };
const ext = MIMES[mime];
if (!ext) throw new Error('MIME inválido: ' + mime + ' post_id=' + cover.post_id);
const size = Buffer.isBuffer(binary.data) ? binary.data.length : Buffer.byteLength(binary.data, 'base64');
if (size > 5 * 1024 * 1024) throw new Error('Arquivo > 5MB: ' + size + ' bytes, post_id=' + cover.post_id);
const supabaseUrl = $('Config').item.json.SUPABASE_URL;
const storagePath = cover.username + '/' + cover.post_id + '.' + ext;
return {
  json: {
    post_id:      cover.post_id,
    username:     cover.username,
    media_type:   cover.media_type,
    cover_strategy: cover.cover_strategy,
    mime_type:    mime,
    storage_path: storagePath,
    upload_url:   supabaseUrl + '/storage/v1/object/instagram-covers/' + storagePath,
    public_url:   supabaseUrl + '/storage/v1/object/public/instagram-covers/' + storagePath
  },
  binary: { data: binary }
};

const valid = $('Validar Download').item.json;
const resp  = $input.item.json;
const httpError = resp?.error;
const uploadOk  = !httpError && !!(resp.Key || resp.Id || resp.id || resp.key);
return { json: {
  post_id:        valid.post_id,
  username:       valid.username,
  media_type:     valid.media_type,
  cover_strategy: valid.cover_strategy,
  storage_path:   valid.storage_path,
  public_url:     valid.public_url,
  upload_ok:      uploadOk,
  upload_error:   uploadOk ? null : (resp.message || resp.error || JSON.stringify(resp))
}};

const v = $input.item.json;
return { json: {
  post_id:     v.post_id     || 'unknown',
  username:    v.username    || 'unknown',
  media_type:  v.media_type  || null,
  status:      'FALHA',
  upload_ok:   false,
  upload_error: v.upload_error || 'upload falhou',
  timestamp:   new Date().toISOString(),
  _nota:       'cover_url mantido NULL — será reprocessado na próxima execução'
}};
